import assert from "node:assert/strict";
import { default as linearRegression } from "./src/linear_regression.js";
import { default as linearRegressionLine } from "./src/linear_regression_line.js";
import { default as weightedLinearRegression } from "./src/weighted_linear_regression.js";
{
{
{
// A perfect line y = 2x + 1, shifted so the x values are the size of
        // a millisecond timestamp. The naive sums lose every significant
        // digit of the variance to cancellation.
        const data = [];
        for (let i = 0; i < 5; i++) {
            data.push([1e11 + i, 2 * i + 1]);
        }
        const { m, b } = linearRegression(data);
        assert.equal(m, 2);
        assert.equal(b, 1 - 2 * 1e11);
}
}
}

