import assert from "node:assert/strict";
import { default as __ns1_linearRegression } from "./src/linear_regression.js";
import { default as __ns1_weightedLinearRegression } from "./src/weighted_linear_regression.js";
const ss = Object.freeze({ linearRegression: __ns1_linearRegression, weightedLinearRegression: __ns1_weightedLinearRegression });
{
{
{
const data = [
            [0, 0],
            [1, 1],
            [2, 2],
            [3, 5]
        ];
        const plain = ss.linearRegression(data);
        for (const w of [1, 4, 0.25]) {
            const weighted = ss.weightedLinearRegression(data, data.map(() => w));
            assert.equal(weighted.m, plain.m);
            assert.equal(weighted.b, plain.b);
        }
}
}
}

